package com.kuswa.clashtimer.core

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.jsonObject

/**
 * `data` ID → display name, loaded from `assets/names.json`
 * (generated by `tools/gen_names.cjs` from the clash-of-clans-data package) with an optional
 * translation overlay (`assets/names.zh.json`) on top.
 */
class NameMap(private val names: Map<Int, String>, private val texts: Texts = Texts()) {

    val size: Int get() = names.size

    fun has(id: Int): Boolean = id in names

    /** Real name, or `Unknown (id)` for IDs added in future game updates. */
    fun name(id: Int): String = names[id] ?: texts.unknownName(id)

    /** Widget label: `Wizard Tower → 17`, `Super Wizard Tower (new)`, `Cake-A-Pult Damage → 8`. */
    fun label(job: Job): String =
        if (job.isNewBuilding) "${title(job)} ${texts.newSuffix}" else "${title(job)} → ${job.targetLevel}"

    /** The name part of [label]: `Wizard Tower`, `Cake-A-Pult Damage` (crafted defense + module). */
    fun title(job: Job): String = when (job.source) {
        JobSource.MODULE -> {
            val defense = job.typeDataId?.let(::name) ?: job.parentDataId?.let(::name) ?: texts.craftedDefense
            "$defense ${name(job.dataId)}"
        }
        else -> name(job.dataId)
    }

    companion object {
        fun fromJson(text: String, overlay: String? = null, texts: Texts = Texts()): NameMap {
            val base = parseNames(text)
            val translated = overlay?.let { parseNames(it) } ?: emptyMap()
            return NameMap(base + translated, texts)
        }

        private fun parseNames(text: String): Map<Int, String> {
            val root = Json.parseToJsonElement(text).jsonObject
            val obj = root["names"] as? JsonObject ?: root
            return obj.entries.mapNotNull { (k, v) ->
                val id = k.toIntOrNull() ?: return@mapNotNull null
                val name = (v as? JsonPrimitive)?.takeIf { it.isString }?.content ?: return@mapNotNull null
                id to name
            }.toMap()
        }
    }
}
